    "skill": "Rhetorical Synthesis",
    "difficulty": "Hard",
    "passage": "While researching a topic, a student has taken the following notes:\n\nDigital Light Synthesis (DLS) is a form of additive manufacturing that utilizes light to rapidly cure liquid resin into high-quality, 3D objects. Step 1: Ultraviolet (UV) light images are projected up into a pool of liquid resin, where the object’s first layer takes shape. Step 2: The partially cured resin object is raised, leaving a thin space (a dead zone ) beneath it for oxygen and liquid resin to flow through. Step 3: The UV light passes through the dead zone — maintaining the flow of resin — and partially cures additional layers of the object. Step 4: When the resin object is complete, it is baked in an oven to complete the curing.\n\nThe student wants to describe how DLS cures 3D objects.",
