    "passage": "While researching a topic, a student has taken the following notes:\n\nLighthouses send out crucial light signals to help ships and other watercraft navigate at night. Before automation, lighthouses were run by lighthouse keepers. Maria Younghans was the lighthouse keeper at Biloxi Light in Mississippi. She held this position from 1867 to 1918. Flora McNeil was the lighthouse keeper at Bridgeport Breakwater Light in Connecticut. She held this position from 1904 to 1920.\n\nThe student wants to emphasize the order in which the two lighthouse keepers began their careers.",
