    "skill": "Rhetorical Synthesis",
    "difficulty": "Hard",
    "passage": "While researching a topic, a student has taken the following notes:\n\nIn a 2023 study, environmental scientist Jazmin Locke-Rodriguez and colleagues tested the use of floating treatment wetlands (FTWs) in Florida. FTWs are artificial floating platforms of plants used to remediate polluted or nutrient-imbalanced water. Finding: FTWs using marigold flowers removed 52% more total phosphorus than the control. Finding: The test yielded 65 market-quality blooms per square meter. The authors concluded marigolds showed “promising potential as a commercially viable remediating crop cultivated on FTWs in South Florida.”\n\nThe student wants to present the findings of the study.",
