    "skill": "Rhetorical Synthesis",
    "difficulty": "Hard",
    "passage": "While researching a topic, a student has taken the following notes:\n\nPhobetor, a name drawn from Greek mythology, is an exoplanet that orbits the star PSR B1257+12, also known as Lich. Phobetor’s mass is 0.01 times that of Jupiter, or 0.01 Jupiter masses. Mastika, which means “gem” or “jewel” in Malay, is an exoplanet that orbits the star HD 179949, also known as Gumala. Mastika’s mass is 0.92 Jupiter masses.\n\nThe student wants to make and support a generalization about exoplanets.",
    "question": "Which choice most effectively uses relevant information from the notes to accomplish this goal?",
    "options": [
      "A. Exoplanets that are named Phobetor orbit Lich, and those that are named Mastika orbit Gumala.",
      "B. Even though Phobetor and Mastika are both exoplanets, their masses are different: Phobetor’s mass is 0.01 Jupiter masses, and Mastika’s is 0.92 Jupiter masses.",
      "C. Many stars have both a designation and a proper name; for instance, PSR B1257+12 is also known as Lich, and HD 179949 is also known as Gumala.",
      "D. Exoplanet names have diverse origins, a fact that can be seen in the cases of Phobetor, a name drawn from Greek mythology, and Mastika, which means “gem” or “jewel” in Malay."
    ],
    "answer": "D",
    "explanation": "Choice D is the best answer. The sentence makes and supports a generalization about exoplanets, noting that the names of exoplanets have diverse origins and supporting this with the examples of the origins of \"Phobetor\" and \"Mastika.\"\n\nChoice A is incorrect. The sentence misrepresents information from the notes, implying that there are multiple exoplanets with the same names. Additionally, the sentence provides no support for its generalization. Choice B is incorrect. The sentence contrasts the masses of two specific exoplanets; it doesn’t make and support a generalization about exoplanets. Choice C is incorrect. The sentence makes and supports a generalization about stars, not exoplanets.",
    "origin": "cb-psat89",
