    "passage": "While researching a topic, a student has taken the following notes:\n\nMarine biologist Camille Jazmin Gaynus studies coral reefs. Coral reefs are vital underwater ecosystems that provide habitats to 25% of all marine species. Reefs can include up to 8,000 species of fish, such as toadfish, seahorses, and clown triggerfish. The Amazon Reef is a coral reef in Brazil. It is one of the largest known reefs in the world.\n\nThe student wants to introduce the scientist and her field of study to a new audience.",
