    "skill": "Rhetorical Synthesis",
    "difficulty": "Hard",
    "passage": "While researching a topic, a student has taken the following notes:\n\nFreddie Wong (born 1985) is a director and special effects artist from the United States. He is best known for the action-comedy web series Video Game High School (VGHS). VGHS premiered in 2012 on RocketJump, a YouTube channel that Wong cocreated. The series was celebrated for its inventive video game – centric world and high-quality special effects. VGHS was nominated for a Producers Guild Award for Outstanding Digital Series.\n\nThe student wants to begin a narrative about Wong’s award-nominated web series.",
    "question": "Which choice most effectively uses relevant information from the notes to accomplish this goal?",
