    "skill": "Rhetorical Synthesis",
    "difficulty": "Hard",
    "passage": "While researching a topic, a student has taken the following notes:\n\nMaika’i Tubbs is a Native Hawaiian sculptor and installation artist. His work has been shown in the United States, Canada, Japan, and Germany, among other places. Many of his sculptures feature discarded objects. His work Erasure (2008) includes discarded audiocassette tapes and magnets. His work Home Grown (2009) includes discarded pushpins, plastic plates and forks, and wood.\n\nThe student wants to emphasize a similarity between the two works.",
