    "difficulty": "Hard",
    "passage": "While researching a topic, a student has taken the following notes:\n\nTwo opposing theories of vision divided scholars for many centuries. The ancient Greek mathematician Euclid (circa 300 BCE) supported the extramission theory. This theory held that the eyes emit a form of radiation that illuminates objects in its range. The ancient Greek philosopher Aristotle (384 –322 BCE) supported the intromission theory. This theory held that objects emit a form of radiation that reaches the eyes. In the eleventh century, Arab mathematician Ibn al-Haytham (965 –1040 CE) largely settled the debate with the first conclusive experiments supporting intromission.\n\nThe student wants to provide a historical overview of the two theories.",
